#!/usr/bin/env python3
"""Build a self-contained offline visual guide from the canonical Markdown docs."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
DOCS=ROOT/'skills/ai-workbench/references'
data={p.stem:p.read_text() for p in sorted(DOCS.glob('*.md'))}
shell=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Workbench Kit · Start here</title>
<style>
:root{--bg:#f5f4ee;--ink:#182f2b;--muted:#61716b;--line:#d6dcd1;--card:#fffef8;--green:#196d56;--lime:#d6ed8c;--dark:#153c33;--blue:#dceaf5}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,a{touch-action:manipulation}button{font:inherit;cursor:pointer}a{color:var(--green);text-underline-offset:3px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #579cd7;outline-offset:4px}.shell{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;padding:32px 22px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:24px}.brand{font-weight:750;line-height:1.15;letter-spacing:-.6px;font-size:24px}.logo{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:11px;background:var(--dark);color:var(--lime);margin-bottom:12px;font-size:23px}.small{font-size:12px;line-height:1.5;color:var(--muted)}.eyebrow{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;font-weight:700;color:var(--green)}nav{display:grid;gap:5px;overflow-y:auto;min-height:0}nav button{background:none;border:0;border-radius:8px;text-align:left;padding:10px 12px;color:var(--muted);font-size:14px}nav button:hover,nav button.active{background:#e4eadc;color:var(--ink)}.sidebottom{margin-top:auto}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);margin-right:5px}.main{max-width:1250px;width:100%;margin:auto;padding:30px 54px 70px}.topline{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;font-size:12px;color:var(--muted)}.badge{border:1px solid var(--line);padding:2px 10px;border-radius:20px}.hero{padding:50px 0 28px;max-width:800px}h1{font:normal clamp(40px,5vw,69px)/1.05 Georgia,serif;letter-spacing:-2.4px;margin:13px 0 22px}h1 em{color:var(--green);font-weight:normal}.lead{font-size:18px;color:var(--muted);max-width:660px}.path-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:25px 0 42px}.path-card{border:1px solid var(--line);border-radius:16px;background:var(--card);padding:23px;display:flex;flex-direction:column;align-items:flex-start}.path-card .num{display:grid;place-items:center;width:36px;height:36px;border:1px solid var(--line);border-radius:50%;font:20px Georgia,serif}.path-card h3{margin:20px 0 5px;font-size:20px;letter-spacing:-.4px}.path-card p{color:var(--muted);font-size:14px;line-height:1.55;margin:0 0 20px}.path-card button,.action{border:0;border-radius:7px;background:var(--dark);color:white;padding:9px 13px;font-size:13px;margin-top:auto}.path-card:nth-child(2){background:#eaf0df}.path-card:nth-child(3){background:#e8eef2}.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:18px;margin:25px 0 16px}h2{font:normal 30px/1.2 Georgia,serif;letter-spacing:-.5px;margin:0}.flow{border-radius:18px;background:var(--dark);color:#f5f6ee;padding:29px}.flow .eyebrow{color:var(--lime)}.flow h3{font-size:21px;font-weight:500;margin:5px 0 20px}.routes{display:flex;gap:7px;flex-wrap:wrap}.route{border:1px solid #6b8777;border-radius:20px;padding:7px 13px;color:#dfebe0;background:none;font-size:12px}.route.active{background:var(--lime);border-color:var(--lime);color:var(--dark)}.chain{display:grid;grid-template-columns:1fr 22px 1.1fr 22px 1fr;align-items:center;gap:12px;margin:24px 0}.node{padding:16px;border:1px solid #5a776a;border-radius:11px;min-height:88px}.node span{display:block;color:#afc3b6;font-size:11px;margin-bottom:6px}.node strong{font-size:15px;font-weight:600}.arrow{text-align:center;color:var(--lime)}.flow-note{font-size:13px;color:#d0dfd0;min-height:42px}.constant{background:#224c3f;color:#d6e6d8;border-radius:8px;padding:12px;font-size:12px}.two-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:28px 0}.box{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:24px}.box h3{font-size:16px;margin:0 0 12px}.box ul{padding-left:20px;font-size:14px;color:var(--muted)}.steps{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.steps span{font-size:12px;border-radius:5px;background:#eaf0e2;padding:6px 9px}.note{font-size:13px;color:var(--muted);border-left:3px solid #b3c58c;padding-left:14px;margin:25px 0}.footer{padding-top:24px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}#reader{display:none}.reader-top{display:flex;justify-content:space-between;align-items:center;margin:30px 0 25px;gap:16px}.reader-top button{border:1px solid var(--line);background:none;border-radius:6px;padding:7px 13px;font-size:12px}.article{max-width:900px}.article h1{font-size:43px;letter-spacing:-1.2px;margin:25px 0}.article h2{margin:40px 0 15px;font-size:28px}.article h3{margin:28px 0 12px}.article p,.article li{font-size:15px}.article li{margin:7px 0}.article pre{background:#173c33;color:#e3efdf;padding:20px;border-radius:10px;overflow:auto;font:13px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace}.article code{font:13px ui-monospace,SFMono-Regular,Menlo,monospace;background:#e6ebdf;padding:2px 5px;border-radius:4px}.article pre code{background:none;padding:0;color:inherit}.article table{border-collapse:collapse;width:100%;font-size:13px;background:var(--card)}.article th,.article td{text-align:left;vertical-align:top;border:1px solid var(--line);padding:11px 12px}.article th{background:#e7edde}.table-wrap{overflow:auto}.article blockquote{border-left:3px solid var(--green);padding:8px 18px;background:#eaf0e2;margin:18px 0}.article blockquote p{margin:0}.doclinks{display:flex;flex-wrap:wrap;gap:9px;margin:18px 0}.doclinks button{border:1px solid var(--line);border-radius:7px;background:var(--card);padding:8px 11px;font-size:12px}.hidden{display:none!important}@media(max-width:1000px){.main{padding:25px}.shell{grid-template-columns:195px 1fr}.sidebar{padding:25px 15px}.path-grid{gap:9px}.path-card{padding:17px}.chain{grid-template-columns:1fr}.arrow{transform:rotate(90deg)}.node{min-height:0}}@media(max-width:720px){.shell{display:block}.sidebar{height:auto;position:relative;border-right:0;border-bottom:1px solid var(--line);padding:18px}.brand{font-size:20px}.logo{display:none}.sidebar nav{display:flex;overflow:auto}.sidebar nav button{white-space:nowrap}.sidebottom,.sidebar>.small{display:none}.main{padding:22px}.hero{padding-top:30px}h1{font-size:48px}.path-grid,.two-grid{grid-template-columns:1fr}.path-card{padding:23px}.chain{margin:18px 0}.topline{gap:12px}.section-title{display:block}.article h1{font-size:36px}}
@media print{.sidebar,.reader-top,.topline,.doclinks{display:none}.shell{display:block}.main{padding:0}.article pre{white-space:pre-wrap}.article table{font-size:11px}a{color:inherit}.path-grid,.two-grid{break-inside:avoid}}
</style></head><body><div class="shell"><aside class="sidebar"><div class="brand"><div class="logo">↗</div><br>AI Workbench<br>Kit</div><div class="small">A calmer way to set up<br>your AI coding workspace.</div><nav aria-label="Main navigation"><button class="active" data-page="home">Overview</button><button data-page="choose-path">Choose your path</button><button data-page="getting-started">01 · Get started</button><button data-page="desktop">02 · Use Desktop</button><button data-page="providers">03 · Choose access</button><button data-page="switching">04 · Switch safely</button><button data-page="continuity">05 · Continue your work</button><button data-page="optimisation">06 · Optimise usage</button><button data-page="configuration">Configuration explained</button><button data-page="recipes">Command recipes</button><button data-page="scripts">Script reference</button><button data-page="ai-skill">AI skill</button></nav><div class="sidebottom small"><span class="live-dot"></span>Works offline<br>No analytics. No account needed.<br><br>v0.2.0 · 24 Nov 2026</div></aside><main class="main"><div class="topline"><span>CLAUDE + CODEX / SETUP & CONTINUITY</span><span class="badge">Independent, open-source toolkit</span></div><div id="home"><section class="hero"><div class="eyebrow">One toolkit. Three ways to use it.</div><h1>Keep your work in place.<br><em>Choose how you access AI.</em></h1><p class="lead">Set up your apps, change providers and make usage visible—with plain guidance, ordinary scripts or an AI assistant.</p></section><div class="path-grid"><article class="path-card"><span class="num">1</span><h3>Follow the guide</h3><p>Plain-language steps for Desktop. Understand what to click, what to check and how to return to the previous setup.</p><button data-page="choose-path">Choose my starting point ↗</button></article><article class="path-card"><span class="num">2</span><h3>Run the scripts</h3><p>Guided setup without JSON editing, explained fields and repeatable checks. Preview first. No AI tokens for the helper commands.</p><button data-page="recipes">Follow a complete recipe ↗</button></article><article class="path-card"><span class="num">3</span><h3>Ask your assistant</h3><p>Install one self-contained skill with setup, switching, continuity and usage workflows. Same guides. Same scripts.</p><button data-page="ai-skill">Use the AI skill ↗</button></article></div><div class="section-title"><h2>Five profiles. Your original workspace.</h2><span class="small">Select an access route below</span></div><section class="flow"><div class="eyebrow">Understand the connection</div><h3>Change the route—not the location of your work.</h3><div class="routes" role="group" aria-label="Access route"><button class="route active" data-route="bedrock">AWS Bedrock</button><button class="route" data-route="foundry">Azure Foundry</button><button class="route" data-route="api">Anthropic API</button><button class="route" data-route="suba">Subscription A</button><button class="route" data-route="subb">Subscription B</button></div><div class="chain"><div class="node"><span>WORK ON YOUR COMPUTER</span><strong>Original project + local Code</strong></div><div class="arrow">→</div><div class="node"><span>AUTHENTICATION</span><strong id="auth">Named AWS profile + region</strong></div><div class="arrow">→</div><div class="node"><span>USAGE IS RECORDED BY</span><strong id="billing">Selected AWS account</strong></div></div><p class="flow-note" id="route-note" aria-live="polite"></p><div class="constant">Stays in place: project folders · source files · saved histories · memory references</div></section><div class="two-grid"><section class="box"><h3>A checkable switching process</h3><div class="steps"><span>1 · Finish active work</span><span>2 · Record context</span><span>3 · Preview</span><span>4 · Switch</span><span>5 · Verify & resume</span></div><p class="small">A file count is not enough. Check the account, billing route, original directory and resumed session context.</p><button class="action" data-page="switching">Open switching guide</button></section><section class="box"><h3>Useful optimisation, measured first</h3><ul><li>Use an appropriate model and effort.</li><li>Keep stable instructions and tools.</li><li>Review cache, model mix and billing.</li><li>Keep large history in referenced files.</li></ul><button class="action" data-page="optimisation">Open usage playbook</button></section></div><p class="note">A terminal wrapper does not switch Desktop. Two subscription labels do not isolate two logins. Local execution still uses the selected cloud model. This kit preserves references and checks continuity; it cannot transfer hidden model state.</p><div class="doclinks"><button data-page="configuration">What do these fields mean?</button><button data-page="recipes">Copy-and-paste recipes</button><button data-page="privacy-and-billing">Privacy & billing</button><button data-page="troubleshooting">Troubleshooting</button><button data-page="sources">Compatibility & official sources</button></div></div><section id="reader"><div class="reader-top"><span class="eyebrow">Field guide / read at your own pace</span><button onclick="window.print()">Print this guide</button></div><article class="article" id="article"></article><div class="doclinks"><button data-page="home">← Back to overview</button><button data-page="troubleshooting">Troubleshooting</button><button data-page="sources">Sources & limitations</button></div></section><footer class="footer">AI Workbench Kit · MIT licensed · No personal configuration or session data included.<br>Models, plans and app controls change. Verify the current official documentation before live changes.</footer></main></div>
<script id="guides" type="application/json">__DATA__</script><script>
'use strict';
const docs=JSON.parse(document.getElementById('guides').textContent);
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function inline(s){let codes=[];s=s.replace(/`([^`]+)`/g,(_,v)=>'@@CODE'+(codes.push('<code>'+esc(v)+'</code>')-1)+'@@');s=esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,href)=>{if(/^(javascript|data):/i.test(href))return label;const key=href.split('/').pop().replace(/\.md(?:#.*)?$/,'');return docs[key]?'<a href="#'+key+'">'+label+'</a>':'<a href="'+(href.startsWith('https:')?href:'skills/ai-workbench/references/'+href)+'"'+(href.startsWith('https:')?' target="_blank" rel="noopener noreferrer"':'')+'>'+label+'</a>';});return s.replace(/@@CODE(\d+)@@/g,(_,n)=>codes[+n]);}
function render(md){const lines=md.split('\n');let html='',i=0;while(i<lines.length){let l=lines[i];if(!l.trim()){i++;continue;}if(l.startsWith('```')){let code=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))code.push(lines[i++]);i++;html+='<pre><code>'+esc(code.join('\n'))+'</code></pre>';continue;}if(l.startsWith('|')){let rows=[];while(i<lines.length&&lines[i].startsWith('|')){const r=lines[i++];if(/^\|[\s:|\-]+\|$/.test(r))continue;rows.push(r.slice(1,-1).replaceAll('\\|','@@PIPE@@').split('|').map(c=>c.replaceAll('@@PIPE@@','|')));}html+='<div class="table-wrap"><table>'+rows.map((r,n)=>'<tr>'+r.map(c=>'<'+(n?'td':'th')+'>'+inline(c.trim())+'</'+(n?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>';continue;}let h=l.match(/^(#{1,3}) (.*)/);if(h){html+='<h'+h[1].length+'>'+inline(h[2])+'</h'+h[1].length+'>';i++;continue;}if(/^[-*] |^\d+\. /.test(l)){let ordered=/^\d+\. /.test(l),tag=ordered?'ol':'ul';html+='<'+tag+'>';while(i<lines.length&&(ordered?/^\d+\. /:/^[-*] /).test(lines[i]))html+='<li>'+inline(lines[i++].replace(/^[-*] |^\d+\. /,''))+'</li>';html+='</'+tag+'>';continue;}if(l.startsWith('> ')){html+='<blockquote><p>'+inline(l.slice(2))+'</p></blockquote>';i++;continue;}let p=[l];i++;while(i<lines.length&&lines[i].trim()&&!/^(#|\||```|> |[-*] |\d+\. )/.test(lines[i]))p.push(lines[i++]);html+='<p>'+inline(p.join(' '))+'</p>';}return html;}
function show(page){if(page!=='home'&&!docs[page])page='home';document.getElementById('home').style.display=page==='home'?'block':'none';document.getElementById('reader').style.display=page==='home'?'none':'block';if(page!=='home')document.getElementById('article').innerHTML=render(docs[page]);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo(0,0);document.title=(page==='home'?'Start here':page.replaceAll('-',' '))+' · AI Workbench Kit';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-page]');if(button){location.hash=button.dataset.page;show(button.dataset.page);}});window.addEventListener('hashchange',()=>show(location.hash.slice(1)||'home'));
const routes={bedrock:['Named AWS profile + region','Selected AWS account','Verify the expected account and principal before using an approved model. No IAM or Marketplace changes are automated.'],foundry:['Foundry resource + API key','Selected Azure subscription','Confirm the deployment and whether its charges qualify for your credits. Deployment status alone does not prove runtime access.'],api:['Anthropic API key reference','Console organisation / workspace','API credits and spend limits are separate from a Claude subscription. Keys stay in your secret store.'],suba:['Native login · account A','Account A subscription','A profile name verifies your intended account. Native sign-in selects it. Shared credentials are not a privacy boundary.'],subb:['Native login · account B','Account B subscription','Same authentication mechanism, another intended account. Pro / Ultra are editable labels, not entitlements provided by this kit.']};
function route(k){const r=routes[k];document.getElementById('auth').textContent=r[0];document.getElementById('billing').textContent=r[1];document.getElementById('route-note').textContent=r[2];document.querySelectorAll('.route').forEach(b=>{b.classList.toggle('active',b.dataset.route===k);b.setAttribute('aria-pressed',String(b.dataset.route===k));});}document.querySelectorAll('.route').forEach(b=>b.addEventListener('click',()=>route(b.dataset.route)));route('bedrock');show(location.hash.slice(1)||'home');
</script></body></html>'''
(ROOT/'START-HERE.html').write_text(shell.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
print('Built START-HERE.html from',len(data),'canonical guides.')
